/**
 * Replaces the hover selector placeholder in a given selector template.
 *
 * In VB, `.et_vb_hover` class is added to the module class which triggers the hover-related rendering,
 * so `{{:hover}}` being replaced with an empty string ('').
 *
 * @template TSelectorTemplate Type of the selector template.
 *
 * @param {object} options An object containing selectors property.
 * @param {TSelectorTemplate} options.selectors The selector template to be modified.
 *
 * @returns {TSelectorTemplate} The modified selector template.
 */
export declare const replaceHoverSelectorPlaceholder: <TSelectorTemplate>({ selectors, }: {
    selectors: TSelectorTemplate;
}) => TSelectorTemplate;
